window.WPS = window.WPS || {};
WPS.WRITE = [
  // ===== レベル1(中学〜高校入試)=====
  // --- 和文英訳 15 ---
  { id: 'W1-01', lv: 1, type: 'trans', title: '和文英訳:経験', prompt: '次の日本語を英語にしなさい。\n「私は一度も京都に行ったことがありません。」', words: '', model: 'I have never been to Kyoto.', alt: ['I\'ve never visited Kyoto.'], ja: '私は一度も京都に行ったことがありません。', points: ['「〜したことがない」は現在完了の経験 have never + 過去分詞', '「行ったことがある」は have been to 〜 を使う'], check: ['現在完了(have + 過去分詞)を使えた', 'never の位置(have と過去分詞の間)が正しい', '文頭は大文字、文末にピリオド'], miss: ['× I have never gone to Kyoto.(have gone は「行ってしまった」で、経験にはふつう使いません)', '× I never have been to Kyoto. → ○ I have never been to Kyoto.'] },
  { id: 'W1-02', lv: 1, type: 'trans', title: '和文英訳:習慣', prompt: '次の日本語を英語にしなさい。\n「私は毎朝7時に起きます。」', words: '', model: 'I get up at seven every morning.', alt: ['I wake up at seven o\'clock every morning.'], ja: '私は毎朝7時に起きます。', points: ['習慣は現在形で表します', '時刻の前は at', 'every morning の前に前置詞はいりません'], check: ['現在形を使えた', '時刻の前に at をつけた', 'every morning に in をつけていない'], miss: ['× I get up at seven in every morning. → ○ I get up at seven every morning.'] },
  { id: 'W1-03', lv: 1, type: 'trans', title: '和文英訳:得意なこと', prompt: '次の日本語を英語にしなさい。\n「彼女はピアノを弾くのが得意です。」', words: '', model: 'She is good at playing the piano.', alt: ['She plays the piano well.'], ja: '彼女はピアノを弾くのが得意です。', points: ['「〜するのが得意だ」は be good at + 動詞の -ing 形', '楽器には the をつけます(play the piano)'], check: ['be good at のあとを -ing 形にした', 'piano の前に the をつけた', '主語 She に合わせて is を使った'], miss: ['× She is good at play the piano.(前置詞 at のあとは -ing 形)', '× She good at playing the piano.(be動詞が必要)'] },
  { id: 'W1-04', lv: 1, type: 'trans', title: '和文英訳:理由', prompt: '次の日本語を英語にしなさい。\n「昨日は雨が降っていたので、私は家にいました。」', words: '', model: 'It was raining yesterday, so I stayed home.', alt: ['I stayed at home yesterday because it was raining.'], ja: '昨日は雨が降っていたので、私は家にいました。', points: ['天気の主語は It', '「〜していた」は過去進行形 was + -ing', '「AなのでB」は A, so B または B because A'], check: ['天気の主語に It を使えた', '過去の文になっている', 'so または because で2つの文をつないだ'], miss: ['× Because it was raining yesterday, so I stayed home.(because と so はいっしょに使いません)'] },
  { id: 'W1-05', lv: 1, type: 'trans', title: '和文英訳:比較', prompt: '次の日本語を英語にしなさい。\n「この本はあの本よりおもしろい。」', words: '', model: 'This book is more interesting than that one.', alt: ['This book is more interesting than that book.'], ja: 'この本はあの本よりおもしろい。', points: ['長い形容詞の比較級は more + 形容詞', '同じ名詞のくり返しをさけるときは one を使います'], check: ['more interesting の形にした', 'than を使って比べる相手を示した', 'book のくり返しを one でさけられた(さけなくても正解)'], miss: ['× This book is interestinger than that one.(interesting は more をつける)', '× This book is more interesting than that.(that one / that book とするのが自然)'] },
  { id: 'W1-06', lv: 1, type: 'trans', title: '和文英訳:許可', prompt: '次の日本語を英語にしなさい。\n「窓を開けてもいいですか。」', words: '', model: 'May I open the window?', alt: ['Can I open the window?', 'Do you mind if I open the window?'], ja: '窓を開けてもいいですか。', points: ['許可を求めるときは May I 〜? / Can I 〜?', 'May I 〜? はていねいな言い方です'], check: ['May I または Can I で始めた', '動詞は原形 open にした', '文末にクエスチョンマークをつけた'], miss: ['× May I opening the window? → ○ May I open the window?'] },
  { id: 'W1-07', lv: 1, type: 'trans', title: '和文英訳:将来の希望', prompt: '次の日本語を英語にしなさい。\n「私の兄は医者になりたがっています。」', words: '', model: 'My brother wants to be a doctor.', alt: ['My older brother wants to become a doctor.'], ja: '私の兄は医者になりたがっています。', points: ['「〜になりたい」は want to be 〜', '主語が3人称単数なので wants', '職業の前には a / an をつけます'], check: ['wants の s を忘れなかった', 'want to のあとを動詞の原形にした', 'doctor の前に a をつけた'], miss: ['× My brother want to be doctor. → ○ My brother wants to be a doctor.'] },
  { id: 'W1-08', lv: 1, type: 'trans', title: '和文英訳:受け身', prompt: '次の日本語を英語にしなさい。\n「この写真は私の父によって撮られました。」', words: '', model: 'This picture was taken by my father.', alt: ['This photo was taken by my father.', 'My father took this picture.'], ja: 'この写真は私の父によって撮られました。', points: ['受け身は be動詞 + 過去分詞', '「〜によって」は by 〜', 'take の過去分詞は taken'], check: ['was + 過去分詞の形にした', 'take の過去分詞 taken を正しく書けた', 'by my father を最後に置いた'], miss: ['× This picture was took by my father.(took は過去形。過去分詞は taken)'] },
  { id: 'W1-09', lv: 1, type: 'trans', title: '和文英訳:道をたずねる', prompt: '次の日本語を英語にしなさい。\n「駅への行き方を教えてくれませんか。」', words: '', model: 'Could you tell me how to get to the station?', alt: ['Can you tell me the way to the station?'], ja: '駅への行き方を教えてくれませんか。', points: ['ていねいな依頼は Could you 〜?', '「〜への行き方」は how to get to 〜 / the way to 〜', '道を口で教えるときは tell を使います'], check: ['Could you(Can you)で始めた', 'how to get to または the way to を使えた', '文末にクエスチョンマークをつけた'], miss: ['× Could you teach me the way to the station?(道を教えるときは teach ではなく tell)'] },
  { id: 'W1-10', lv: 1, type: 'trans', title: '和文英訳:関係代名詞', prompt: '次の日本語を英語にしなさい。\n「私には英語を話す友達がいます。」', words: '', model: 'I have a friend who speaks English.', alt: ['I have a friend who can speak English.'], ja: '私には英語を話す友達がいます。', points: ['人を説明するときは関係代名詞 who', '「〜がいる」は I have 〜 で表せます', 'a friend は3人称単数なので speaks'], check: ['who を使って friend を後ろから説明した', 'speaks の s を忘れなかった', '「友達がいる」を I have a friend で表した'], miss: ['× I have a friend who speak English. → ○ who speaks English', '× I have a friend which speaks English.(人には who)'] },
  { id: 'W1-11', lv: 1, type: 'trans', title: '和文英訳:時を表す接続詞', prompt: '次の日本語を英語にしなさい。\n「宿題を終えたら、テレビを見てもいいよ。」', words: '', model: 'You can watch TV after you finish your homework.', alt: ['When you finish your homework, you can watch TV.'], ja: '宿題を終えたら、テレビを見てもいいよ。', points: ['「〜してもいい」は can', 'after / when の中では、未来のことでも現在形を使います'], check: ['can で許可を表した', 'after / when のあとを現在形にした', 'your homework と所有格をつけた'], miss: ['× after you will finish your homework → ○ after you finish your homework'] },
  { id: 'W1-12', lv: 1, type: 'trans', title: '和文英訳:継続', prompt: '次の日本語を英語にしなさい。\n「彼は3年間ずっとこの町に住んでいます。」', words: '', model: 'He has lived in this town for three years.', alt: ['He has been living in this town for three years.'], ja: '彼は3年間ずっとこの町に住んでいます。', points: ['過去から今まで続いていることは現在完了(継続)', '期間は for 〜、始まった時点は since 〜'], check: ['has + 過去分詞を使えた', '期間を for で表した', 'live in 〜 の in を忘れなかった'], miss: ['× He lives in this town for three years.(継続は現在完了)', '× He has lived in this town since three years.(期間には for)'] },
  { id: 'W1-13', lv: 1, type: 'trans', title: '和文英訳:条件', prompt: '次の日本語を英語にしなさい。\n「明日晴れたら、海に行きましょう。」', words: '', model: 'If it is sunny tomorrow, let\'s go to the beach.', alt: ['Let\'s go to the sea if it\'s sunny tomorrow.'], ja: '明日晴れたら、海に行きましょう。', points: ['条件を表す if の中は、未来のことでも現在形', '「〜しましょう」は Let\'s + 動詞の原形'], check: ['if のあとを現在形にした', 'Let\'s のあとを動詞の原形にした', 'If 〜 を前に置くときはコンマで区切った'], miss: ['× If it will be sunny tomorrow → ○ If it is sunny tomorrow'] },
  { id: 'W1-14', lv: 1, type: 'trans', title: '和文英訳:疑問詞 + to', prompt: '次の日本語を英語にしなさい。\n「私は何を言えばいいのかわかりませんでした。」', words: '', model: 'I didn\'t know what to say.', alt: ['I did not know what I should say.'], ja: '私は何を言えばいいのかわかりませんでした。', points: ['「何を〜すればよいか」は what to + 動詞の原形', '過去の否定は didn\'t + 動詞の原形'], check: ['what to say の形を使えた', 'didn\'t のあとを原形 know にした', '文末はピリオド(疑問文ではない)'], miss: ['× I didn\'t know what to say?(ふつうの文なのでピリオド)', '× I didn\'t knew what to say. → ○ I didn\'t know'] },
  { id: 'W1-15', lv: 1, type: 'trans', title: '和文英訳:too 〜 to …', prompt: '次の日本語を英語にしなさい。\n「この机は重すぎて私には運べません。」', words: '', model: 'This desk is too heavy for me to carry.', alt: ['This desk is so heavy that I can\'t carry it.'], ja: 'この机は重すぎて私には運べません。', points: ['「…すぎて〜できない」は too + 形容詞 + to + 動詞の原形', '「私には」は for me を to の前に置きます', 'so 〜 that S can\'t … でも表せます'], check: ['too 〜 to … の形を使えた', 'for me の位置が正しい', 'so 〜 that を使う場合は can\'t carry it と it を入れた'], miss: ['× This desk is too heavy for me to carry it.(主語の desk が carry の目的語なので it は不要)', '× This desk is so heavy that I can\'t carry.(so 〜 that の文では it が必要)'] },

  // --- 自由英作文 6(20〜35語)---
  { id: 'W1-16', lv: 1, type: 'free', title: '自由英作文:好きな季節', prompt: 'What is your favorite season? Write about it and give a reason.', words: '20〜35語', model: 'My favorite season is summer. I like swimming in the sea with my friends. Also, summer vacation is long, so I can enjoy many things, like camping and festivals.', alt: [], ja: '私のいちばん好きな季節は夏です。友達と海で泳ぐのが好きです。また、夏休みは長いので、キャンプやお祭りなど、たくさんのことを楽しめます。', points: ['My favorite season is 〜. で始めると書きやすい', '理由は I like -ing 〜. / Also, 〜. で加える', 'so(だから)や like(〜のような)で文を広げる'], check: ['最初に好きな季節をはっきり書いた', '理由を1つ以上書いた', '指定の語数に入っている', '動詞の形(三単現・時制)のミスがない'], miss: ['× My favorite season is a summer. → ○ My favorite season is summer.(季節名にはふつう a をつけない)', '× I like swim in the sea. → ○ I like swimming in the sea.'] },
  { id: 'W1-17', lv: 1, type: 'free', title: '自由英作文:週末の出来事', prompt: 'What did you do last weekend? Write about it.', words: '20〜35語', model: 'Last Sunday, I went to the zoo with my family. We saw many animals, and the baby pandas were very cute. After that, we ate lunch in the park. I had a great time.', alt: [], ja: 'この前の日曜日、私は家族と動物園に行きました。たくさんの動物を見て、パンダの赤ちゃんはとてもかわいかったです。そのあと、公園で昼食を食べました。とても楽しい時間を過ごしました。', points: ['過去のことなので動詞は過去形', 'After that(そのあと)で出来事を順番に並べる', '最後に I had a great time. などで感想を書く'], check: ['すべての動詞を過去形にした', 'いつ・だれと・どこへを書いた', '最後に感想を書いた', '指定の語数に入っている'], miss: ['× I go to the zoo last Sunday. → ○ I went to the zoo last Sunday.', '× I went to the zoo with my family at last Sunday.(last Sunday の前に前置詞はいらない)'] },
  { id: 'W1-18', lv: 1, type: 'free', title: '自由英作文:将来の夢', prompt: 'What do you want to be in the future? Write your dream and the reason.', words: '20〜35語', model: 'I want to be a nurse in the future. When I was in the hospital, a kind nurse helped me a lot. I want to help sick people like her. So I will study hard.', alt: [], ja: '私は将来、看護師になりたいです。入院していたとき、やさしい看護師さんがとても助けてくれました。私も彼女のように病気の人を助けたいです。だから、一生懸命勉強するつもりです。', points: ['I want to be a(an) 〜. で夢を示す', 'When I was 〜, …. で理由となる経験を書く', '最後に I will 〜. でこれからの決意を書く'], check: ['なりたい職業をはっきり書いた', '理由や経験を書いた', '職業名の前に a / an をつけた', '指定の語数に入っている'], miss: ['× I want to be nurse. → ○ I want to be a nurse.', '× I want to help sick people like she. → ○ like her(前置詞のあとは目的格)'] },
  { id: 'W1-19', lv: 1, type: 'free', title: '自由英作文:朝食はごはんかパンか', prompt: 'Which do you like better for breakfast, rice or bread? Write your answer and the reasons.', words: '20〜35語', model: 'I like rice better than bread. Rice keeps me full until lunch, so I can study hard in the morning. Also, I like eating rice with miso soup and fish.', alt: [], ja: '私はパンよりごはんのほうが好きです。ごはんは昼食までおなかがもつので、午前中しっかり勉強できます。また、ごはんをみそ汁や魚といっしょに食べるのが好きです。', points: ['I like A better than B. で答える', 'keep me full(おなかがもつ)など、具体的な理由を書く', 'Also, で2つ目の理由を加える'], check: ['質問にまっすぐ答えた(A better than B)', '理由を2つ書いた', '三単現の s(Rice keeps)を忘れなかった', '指定の語数に入っている'], miss: ['× I like rice better than a bread.(bread は数えられないので a をつけない)', '× I like rice more better than bread. → ○ better than'] },
  { id: 'W1-20', lv: 1, type: 'free', title: '自由英作文:学校の紹介', prompt: 'A new student from another country is coming to your school. Write a message to introduce your school.', words: '20〜35語', model: 'Our school is near a big park. We have about five hundred students. Many students join club activities after school. The school festival in October is very exciting. You will love it!', alt: [], ja: '私たちの学校は大きな公園の近くにあります。生徒は約500人います。多くの生徒が放課後に部活動に参加しています。10月の文化祭はとても盛り上がります。きっと気に入りますよ!', points: ['場所・人数・行事など、具体的な情報を並べる', 'We have 〜.(〜がある・いる)は学校紹介で便利', '最後に相手への一言を入れると自然'], check: ['学校の特徴を2つ以上書いた', '数字や月など具体的な情報を入れた', '読み手(転入生)に向けた一言を書いた', '指定の語数に入っている'], miss: ['× There is five hundred students. → ○ There are about five hundred students. / We have about five hundred students.', '× The school festival on October is very exciting. → ○ in October(月の前は in)'] },
  { id: 'W1-21', lv: 1, type: 'free', title: '意見:都会と田舎', prompt: 'Is it better to live in a city or in the country? Write your opinion and the reasons.', words: '20〜35語', model: 'I think it is better to live in the country. The air is clean, and it is quiet. Also, we can grow vegetables and enjoy nature every day.', alt: [], ja: '私は田舎に住むほうがよいと思います。空気がきれいで、静かです。また、野菜を育てたり、毎日自然を楽しんだりできます。', points: ['I think it is better to 〜. で意見を書く', '理由は and や Also, でつなげる', '「田舎」は the country / the countryside'], check: ['最初に意見をはっきり書いた', '理由を2つ以上書いた', '指定の語数に入っている', 'it is better to のあとを動詞の原形にした'], miss: ['× I think it is better to live in country. → ○ in the country', '× I think it is better to living in the country. → ○ better to live'] },

  // --- メール返信 4(20〜35語)---
  { id: 'W1-22', lv: 1, type: 'email', title: 'メール:持ち物のアドバイス', prompt: 'あなたはカナダの友達 Tom から次のメールを受け取りました。返信を書きなさい(あいさつと署名もふくめて数えます)。\n\nHi!\nI\'m coming to Japan next month. It\'s my first visit. What should I bring?\nTom', words: '20〜35語', model: 'Hi Tom,\nI\'m happy to hear that! It will be cold next month, so please bring a warm coat. Also, bring comfortable shoes because we will walk a lot.\nSee you soon,\nKenta', alt: [], ja: 'トムへ\nそれを聞いてうれしいです!来月は寒くなるので、暖かいコートを持ってきてください。それから、たくさん歩くので、歩きやすい靴も持ってきてね。\nまたすぐに会おうね\nケンタ', points: ['最初に相手のメールへの反応(I\'m happy to hear that!)を書く', 'please bring 〜 で持ち物を伝える', 'so / because で理由をそえる'], check: ['あいさつ(Hi Tom,)と署名を書いた', '質問(何を持っていくべきか)に答えた', '持ち物の理由を書いた', '指定の語数に入っている'], miss: ['× Please bring warm coat. → ○ Please bring a warm coat.', '× It will cold next month. → ○ It will be cold next month.'] },
  { id: 'W1-23', lv: 1, type: 'email', title: 'メール:誘いを断る', prompt: '友達の Emma から次のメールが届きました。行けないことを、理由をそえて伝える返信を書きなさい(あいさつと署名もふくめて数えます)。\n\nHi,\nI\'m having a birthday party this Saturday. Can you come?\nEmma', words: '20〜35語', model: 'Hi Emma,\nThank you for inviting me. I\'m sorry, but I can\'t come on Saturday because I have a piano lesson. I hope you have a great party!\nBest,\nYuki', alt: [], ja: 'エマへ\n誘ってくれてありがとう。ごめんね、土曜日はピアノのレッスンがあるので行けません。すてきなパーティーになるといいね!\nユキより', points: ['まずお礼:Thank you for inviting me.', '断るときは I\'m sorry, but I can\'t 〜. と理由をそえる', '最後に相手を気づかう一言を書く'], check: ['お礼の言葉を書いた', '行けないことと理由を書いた', '相手を気づかう一言を書いた', '指定の語数に入っている'], miss: ['× Thank you for invite me. → ○ Thank you for inviting me.', '× I can\'t go to your party in Saturday. → ○ on Saturday'] },
  { id: 'W1-24', lv: 1, type: 'email', title: 'メール:ホストファミリーへ', prompt: 'ホームステイ先の Mr. Brown から次のメールが届きました。返信を書きなさい(あいさつと署名もふくめて数えます)。\n\nDear Riku,\nWe are excited to meet you. What food do you like? Is there any food you can\'t eat?\nJohn Brown', words: '20〜35語', model: 'Dear Mr. Brown,\nThank you for your email. I like pasta and fish very much. I can eat almost everything, but I can\'t eat eggs. I\'m looking forward to meeting you.\nSincerely,\nRiku', alt: [], ja: 'ブラウンさんへ\nメールをありがとうございます。私はパスタと魚が大好きです。ほとんど何でも食べられますが、卵は食べられません。お会いできるのを楽しみにしています。\nリク', points: ['質問が2つあるので、両方に答える', 'I\'m looking forward to -ing(〜するのを楽しみにしている)', '目上の人には Dear Mr. 〜, / Sincerely, を使う'], check: ['好きな食べ物を答えた', '食べられない物について答えた', 'ていねいなあいさつと結びを書いた', '指定の語数に入っている'], miss: ['× I\'m looking forward to meet you. → ○ I\'m looking forward to meeting you.', '× I can eat almost everything, but I can\'t eat egg. → ○ eggs'] },
  { id: 'W1-25', lv: 1, type: 'email', title: 'メール:日本の正月', prompt: 'アメリカの友達 Lucy から次のメールが届きました。返信を書きなさい(あいさつと署名もふくめて数えます)。\n\nHi,\nWhat do Japanese people usually do on New Year\'s Day?\nLucy', words: '20〜35語', model: 'Hi Lucy,\nOn New Year\'s Day, many Japanese people visit a shrine. We also eat special food called osechi. Children get money from their family. It\'s fun!\nTake care,\nMio', alt: [], ja: 'ルーシーへ\n元日には、多くの日本人が神社にお参りします。おせちという特別な料理も食べます。子どもたちは家族からお金(お年玉)をもらいます。楽しいですよ!\nまたね\nミオ', points: ['日本独自のものは 〜 called …(…と呼ばれる〜)で説明する', 'many Japanese people / We で一般的な習慣を表す', '習慣なので現在形で書く'], check: ['質問に答えて、習慣を2つ以上書いた', '日本語の言葉に説明をつけた', '現在形で書いた', '指定の語数に入っている'], miss: ['× On New Year\'s Day, many Japanese people visits a shrine. → ○ visit', '× We also eat special food calling osechi. → ○ called osechi(「〜と呼ばれる」は過去分詞)'] },

  // ===== レベル2(共通テスト〜中堅大)=====
  // --- 和文英訳 10 ---
  { id: 'W2-01', lv: 2, type: 'trans', title: '和文英訳:〜のおかげで', prompt: '次の日本語を英語にしなさい。\n「スマートフォンのおかげで、いつでもどこでも情報を得られるようになった。」', words: '', model: 'Thanks to smartphones, we can now get information anytime and anywhere.', alt: ['Smartphones have made it possible for us to get information whenever and wherever we want.'], ja: 'スマートフォンのおかげで、いつでもどこでも情報を得られるようになった。', points: ['「〜のおかげで」は thanks to 〜', '「〜できるようになった」は can now 〜 や make it possible for A to 〜 で表せる', 'information は数えられない名詞'], check: ['thanks to または make it possible を使えた', '主語(we など)を補った', 'information に s をつけていない'], miss: ['× we can get informations → ○ we can get information', '× Thanks for smartphones, …(「〜のおかげで」は thanks to)'] },
  { id: 'W2-02', lv: 2, type: 'trans', title: '和文英訳:仮定法過去完了', prompt: '次の日本語を英語にしなさい。\n「もっと早く起きていれば、電車に間に合っただろうに。」', words: '', model: 'If I had gotten up earlier, I would have caught the train.', alt: ['If I had woken up earlier, I would have been in time for the train.'], ja: 'もっと早く起きていれば、電車に間に合っただろうに。', points: ['過去の事実と反対の仮定は If S had + 過去分詞, S would have + 過去分詞', '「電車に間に合う」は catch the train / be in time for the train', '主語「私は」を補う'], check: ['if 節を had + 過去分詞にした', '主節を would have + 過去分詞にした', '「間に合う」を catch / be in time for で表した'], miss: ['× If I got up earlier, I could catch the train.(これは現在の仮定)', '× If I would have gotten up earlier, …(if 節に would は入れない)'] },
  { id: 'W2-03', lv: 2, type: 'trans', title: '和文英訳:〜だとわかる', prompt: '次の日本語を英語にしなさい。\n「彼が言ったことは本当だとわかった。」', words: '', model: 'What he said turned out to be true.', alt: ['It turned out that what he said was true.'], ja: '彼が言ったことは本当だとわかった。', points: ['「〜したこと」は関係代名詞 what', '「結果的に〜だとわかる」は turn out (to be) 〜', 'It turns out that 〜 の形も使える'], check: ['what he said を主語にできた', 'turn out to be / It turned out that を使えた', '時制を過去にそろえた'], miss: ['× The thing what he said was true.(the thing と what はいっしょに使わない)', '× That he said turned out to be true.(「言ったこと」は what)'] },
  { id: 'W2-04', lv: 2, type: 'trans', title: '和文英訳:形式主語', prompt: '次の日本語を英語にしなさい。\n「健康のためには、十分な睡眠をとることが大切だ。」', words: '', model: 'It is important to get enough sleep for your health.', alt: ['Getting enough sleep is important for good health.'], ja: '健康のためには、十分な睡眠をとることが大切だ。', points: ['「〜することは大切だ」は It is important to 〜', '「睡眠をとる」は get / have enough sleep', '動名詞(Getting 〜)を主語にしてもよい'], check: ['It is 〜 to … の形、または動名詞の主語を使えた', '「十分な睡眠」を enough sleep にした', 'sleep に a や s をつけていない'], miss: ['× It is important to take enough sleeps. → ○ get enough sleep', '× Get enough sleep is important.(主語にするなら Getting)'] },
  { id: 'W2-05', lv: 2, type: 'trans', title: '和文英訳:比較の強調', prompt: '次の日本語を英語にしなさい。\n「その店は思っていたよりずっと混んでいた。」', words: '', model: 'The store was much more crowded than I had expected.', alt: ['The shop was far more crowded than I thought.'], ja: 'その店は思っていたよりずっと混んでいた。', points: ['比較級を強めるのは much / far(very は使えない)', '「混んでいる」は crowded', '「思っていたより」は than I (had) expected / than I thought'], check: ['much / far で比較級を強めた', 'crowded を使えた', 'than のあとを過去(または過去完了)にした'], miss: ['× The store was very more crowded than I expected.(比較級に very は使えない)', '× The store was more crowded than I think.(時制をそろえる)'] },
  { id: 'W2-06', lv: 2, type: 'trans', title: '和文英訳:関係副詞', prompt: '次の日本語を英語にしなさい。\n「この町は私が生まれた場所です。」', words: '', model: 'This is the town where I was born.', alt: ['This town is the place where I was born.', 'This is the town I was born in.'], ja: 'この町は私が生まれた場所です。', points: ['場所を説明するのは関係副詞 where', '「生まれる」は be born(受け身の形)', 'the town I was born in のように前置詞を最後に残す形もある'], check: ['where を使って場所を説明できた', 'was born の形にした', 'where のあとに in を重ねていない'], miss: ['× This is the town where I was born in.(where と in の重複)', '× This is the town which I was born.(which なら in が必要)'] },
  { id: 'W2-07', lv: 2, type: 'trans', title: '和文英訳:無生物主語', prompt: '次の日本語を英語にしなさい。\n「外国語を学ぶことで、ほかの文化を理解できるようになる。」', words: '', model: 'Learning a foreign language helps us understand other cultures.', alt: ['By learning a foreign language, we can come to understand other cultures.'], ja: '外国語を学ぶことで、ほかの文化を理解できるようになる。', points: ['「〜することで…できる」は、動名詞を主語にして help A (to) 〜 で表すと英語らしい', '「〜するようになる」は come to 〜', 'other のあとの名詞は複数形(other cultures)'], check: ['動名詞の主語、または By -ing を使えた', 'help us understand の形が正しい', 'other cultures と複数形にした'], miss: ['× Learning a foreign language helps us understanding other cultures. → ○ helps us understand', '× we can understand other culture → ○ other cultures'] },
  { id: 'W2-08', lv: 2, type: 'trans', title: '和文英訳:〜せずに', prompt: '次の日本語を英語にしなさい。\n「彼女は一言も言わずに部屋を出て行った。」', words: '', model: 'She left the room without saying a word.', alt: ['She left the room without saying anything.'], ja: '彼女は一言も言わずに部屋を出て行った。', points: ['「〜せずに」は without + -ing', '「一言も言わずに」は without saying a word', 'leave は「〜を出る」の意味で、前置詞なしで目的語をとる'], check: ['without のあとを -ing 形にした', 'leave の過去形 left を使えた', 'left のあとに from を入れていない'], miss: ['× She left from the room …(leave the room で「部屋を出る」)', '× without say a word → ○ without saying a word'] },
  { id: 'W2-09', lv: 2, type: 'trans', title: '和文英訳:there is 構文', prompt: '次の日本語を英語にしなさい。\n「私たちが環境のためにできることはたくさんある。」', words: '', model: 'There are many things we can do for the environment.', alt: ['We can do a lot of things to protect the environment.'], ja: '私たちが環境のためにできることはたくさんある。', points: ['「〜がたくさんある」は There are many 〜', 'things のあとに we can do を続けて説明する(関係代名詞の省略)', '「環境」は the environment'], check: ['There are 〜 で始めた(または We can do を主語・動詞にした)', 'things we can do の語順が正しい', 'environment の前に the をつけた'], miss: ['× There are many things we can do it for the environment.(it は不要)', '× for environment → ○ for the environment'] },
  { id: 'W2-10', lv: 2, type: 'trans', title: '和文英訳:使役の make', prompt: '次の日本語を英語にしなさい。\n「その映画を見て、私はもっと歴史を学びたくなった。」', words: '', model: 'The movie made me want to learn more about history.', alt: ['After watching the movie, I wanted to learn more about history.'], ja: 'その映画を見て、私はもっと歴史を学びたくなった。', points: ['「Aを見てBしたくなった」は、Aを主語にして A made me want to B と表せる', 'make + 人 + 動詞の原形', '「もっと学ぶ」は learn more about 〜'], check: ['make + 人 + 原形の形にした(または After -ing で書いた)', 'want to のあとを原形にした', 'history に the をつけていない'], miss: ['× The movie made me to want to learn …(make のあとは to なしの原形)', '× learn more about the history → ○ learn more about history(一般的な「歴史」)'] },

  // --- 自由英作文 8(50〜80語)---
  { id: 'W2-11', lv: 2, type: 'free', title: '意見:制服', prompt: 'Do you think high school students should wear school uniforms? Write your opinion with two reasons.', words: '60〜80語', model: 'I think high school students should wear school uniforms. First, students do not have to think about what to wear every morning. This saves time, and they can focus on their studies. Second, uniforms help students feel that they belong to their school. For example, when they join events together in the same uniform, they feel a strong sense of unity. For these reasons, I believe school uniforms are a good idea.', alt: [], ja: '私は高校生は制服を着るべきだと思います。第一に、生徒は毎朝何を着るかを考えなくてすみます。これで時間が節約でき、勉強に集中できます。第二に、制服は生徒に自分がその学校の一員だと感じさせてくれます。たとえば、同じ制服で行事に参加すると、強い一体感を感じます。これらの理由から、私は制服はよい考えだと思います。', points: ['I think 〜 should …. → First, 〜. Second, 〜. → For these reasons, 〜. の型', 'For example, で具体例をつける', 'a sense of unity(一体感)、focus on 〜(〜に集中する)'], check: ['最初に意見をはっきり書いた', '理由を2つ書き、それぞれに説明や具体例をつけた', '最後にもう一度意見をまとめた', '指定の語数に入っている', '三単現・時制・冠詞のミスがない'], miss: ['× Uniform help students … → ○ Uniforms help students …(主語と動詞の一致)', '× students don\'t have to think what to wear → ○ think about what to wear'] },
  { id: 'W2-12', lv: 2, type: 'free', title: '意見:オンライン授業と対面授業', prompt: 'Which is better for students, online classes or classes at school? Write your opinion with reasons.', words: '50〜80語', model: 'I think classes at school are better than online classes. First, students can ask teachers questions easily in the classroom. If they do not understand something, they can get help right away. Second, students can learn from their classmates. For example, group discussions help them see different ideas. Online classes are useful, but I believe learning at school is more effective.', alt: [], ja: '私は学校での授業のほうがオンライン授業よりよいと思います。第一に、教室では生徒が先生に気軽に質問できます。わからないことがあれば、すぐに助けてもらえます。第二に、生徒はクラスメートから学ぶことができます。たとえば、グループでの話し合いは、さまざまな考えに気づかせてくれます。オンライン授業も役に立ちますが、私は学校で学ぶほうが効果的だと思います。', points: ['A is better than B. で立場を明確に', 'right away(すぐに)、learn from 〜(〜から学ぶ)', '最後に反対側の良さを認めつつ(〜 is useful, but …)結論を書くと説得力が増す'], check: ['どちらがよいかをはっきり書いた', '理由を2つ書いた', '具体例を入れた', '指定の語数に入っている', '名詞の単数・複数のミスがない'], miss: ['× Students can ask questions to teachers easily.(ask + 人 + 質問 の語順が自然)', '× group discussions help them to seeing → ○ help them see'] },
  { id: 'W2-13', lv: 2, type: 'free', title: '意見:高校生のアルバイト', prompt: 'Some people say that high school students should have part-time jobs. Do you agree? Write your opinion with reasons.', words: '50〜80語', model: 'I agree that high school students should have part-time jobs. First, they can learn how hard it is to earn money. As a result, they will use money more carefully. Second, they can meet people of different ages at work. For example, talking with customers and older coworkers improves their communication skills. However, they should not work too much, so that they still have time to study.', alt: [], ja: '私は高校生がアルバイトをすべきだという意見に賛成です。第一に、お金をかせぐことがどれほど大変かを学べます。その結果、お金をより大切に使うようになるでしょう。第二に、職場でさまざまな年代の人と出会えます。たとえば、お客さんや年上の同僚と話すことで、コミュニケーション力が高まります。ただし、勉強する時間を残せるように、働きすぎるべきではありません。', points: ['I agree that 〜. で賛否を示す', 'how hard it is to 〜(〜することがどれほど大変か)', 'However, で条件や注意点を加えると考えの深さが伝わる'], check: ['賛成か反対かをはっきり書いた', '理由を2つ書き、それぞれ説明をつけた', '指定の語数に入っている', '動名詞主語(talking 〜)のあとの動詞を単数にした', '時制のミスがない'], miss: ['× they can learn how it is hard to earn money → ○ how hard it is to earn money', '× talking with customers improve → ○ improves(動名詞の主語は単数扱い)'] },
  { id: 'W2-14', lv: 2, type: 'free', title: '意見:紙の本と電子書籍', prompt: 'Which do you prefer, paper books or e-books? Explain why.', words: '50〜80語', model: 'I prefer paper books to e-books. First, paper books are easier on my eyes. When I read on a screen for a long time, my eyes get tired. Second, I can remember the content better with paper books because I can write notes in them and see how much I have read. For these reasons, I think paper books are better for studying.', alt: [], ja: '私は電子書籍より紙の本のほうが好きです。第一に、紙の本は目にやさしいです。画面で長時間読むと、目が疲れてしまいます。第二に、紙の本は書き込みができ、どれだけ読んだかも目で見てわかるので、内容をよりよく覚えられます。これらの理由から、勉強には紙の本のほうがよいと思います。', points: ['prefer A to B(BよりAを好む)', 'be easy on one\'s eyes(目にやさしい)', '自分の体験(my eyes get tired)を理由に使うと具体的になる'], check: ['どちらを好むかをはっきり書いた', '理由を2つ書いた', '指定の語数に入っている', 'prefer A to B の形を正しく使えた(than にしていない)'], miss: ['× I prefer paper books than e-books. → ○ prefer paper books to e-books', '× my eyes get tiring → ○ my eyes get tired'] },
  { id: 'W2-15', lv: 2, type: 'free', title: '自由英作文:修学旅行で行きたい場所', prompt: 'If you could choose, where would you like to go on a school trip? Explain your reasons.', words: '50〜80語', model: 'I would like to go to Okinawa on a school trip. First, I want to learn about its history. Okinawa has a unique culture, and I think visiting places related to the war will help us think about peace. Second, I want to experience its beautiful nature. For example, we could swim in the clear sea and see colorful fish. That would be an unforgettable experience.', alt: [], ja: '私は修学旅行で沖縄に行きたいです。第一に、沖縄の歴史について学びたいです。沖縄には独自の文化があり、戦争に関係のある場所を訪れることは、平和について考えるきっかけになると思います。第二に、美しい自然を体験したいです。たとえば、透き通った海で泳いで、色とりどりの魚を見ることができるでしょう。それは忘れられない経験になるはずです。', points: ['質問が would なので I would like to 〜. で答える', 'places related to 〜(〜に関係のある場所)', '想像の内容は could / would を使う'], check: ['行きたい場所をはっきり書いた', '理由を2つ書いた', '具体例を入れた', '指定の語数に入っている', '冠詞(a unique culture / the clear sea)のミスがない'], miss: ['× I would like to go to Okinawa in a school trip. → ○ on a school trip', '× visiting places related to the war help us → ○ helps us(動名詞の主語は単数扱い)'] },
  { id: 'W2-16', lv: 2, type: 'free', title: '意見:コンビニの24時間営業', prompt: 'Do you think convenience stores should be open 24 hours a day? Write your opinion with reasons.', words: '50〜80語', model: 'I do not think convenience stores need to be open 24 hours a day. First, few customers come late at night, so staying open wastes a lot of electricity. Second, it is hard to find workers for night shifts, and working at night is bad for their health. If stores close at midnight, both the environment and workers will benefit.', alt: [], ja: '私はコンビニが24時間営業する必要はないと思います。第一に、深夜に来る客は少ないので、営業を続けると多くの電気をむだにします。第二に、夜勤の働き手を見つけるのは難しく、夜に働くことは健康に悪いです。店が深夜0時に閉まれば、環境にも働く人にもよいことがあるでしょう。', points: ['反対意見は I do not think 〜. と否定を前に出すのが英語らしい', 'few(ほとんどない)と a few(少しある)の違いに注意', 'both A and B will benefit(AにもBにも利益がある)'], check: ['最初に意見をはっきり書いた', '理由を2つ書いた', '最後に提案やまとめを書いた', '指定の語数に入っている', 'few / a few を正しく使い分けた'], miss: ['× Few customers come late at night, so staying open waste a lot of electricity. → ○ wastes(動名詞の主語は単数扱い)', '× it is hard to find workers for night shift → ○ night shifts'] },
  { id: 'W2-17', lv: 2, type: 'free', title: '自由英作文:高校生活で大切なこと', prompt: 'What do you think is the most important thing to do in high school? Explain your answer.', words: '50〜80語', model: 'I think the most important thing to do in high school is to make good friends. First, friends support us when we have problems. For example, when I failed a test, my friends encouraged me and studied with me. Second, friends we make in high school often stay with us for life. That is why I value my time with friends.', alt: [], ja: '私は高校でいちばん大切なことは、よい友達をつくることだと思います。第一に、友達は困ったときに支えてくれます。たとえば、私がテストで失敗したとき、友達ははげましてくれて、いっしょに勉強してくれました。第二に、高校でできた友達は一生の友達になることが多いです。だから私は友達と過ごす時間を大切にしています。', points: ['The most important thing is to 〜. の形', '自分の経験を For example, で入れると具体的になる', 'That is why 〜.(そういうわけで〜)で締める'], check: ['いちばん大切なことをはっきり書いた', '理由を2つ書いた', '具体例(経験)を入れた', '指定の語数に入っている', '時制(経験は過去形)のミスがない'], miss: ['× The most important thing is make good friends. → ○ is to make good friends', '× friends we make in high school often stays → ○ stay'] },
  { id: 'W2-18', lv: 2, type: 'free', title: '意見:宿題にAIを使うこと', prompt: 'Do you think it is a good idea for students to use AI tools for their homework? Write your opinion with reasons.', words: '50〜80語', model: 'I think using AI tools for homework can be a good idea if students use them wisely. First, AI can explain difficult points in simple words, so students can understand lessons better. Second, it can give quick feedback on writing. However, if students just copy answers, they will not learn anything. Therefore, they should use AI as a helper, not as a replacement for thinking.', alt: [], ja: '私は、生徒が賢く使うのであれば、宿題にAIツールを使うのはよい考えになりうると思います。第一に、AIは難しい点をやさしい言葉で説明できるので、生徒は授業をよりよく理解できます。第二に、作文にすばやく意見(フィードバック)をくれます。しかし、生徒が答えを写すだけなら、何も身につきません。したがって、AIは考えることの代わりではなく、手助けとして使うべきです。', points: ['条件つきの賛成は 〜 can be a good idea if …', 'give feedback on 〜(〜について意見を返す)', 'not as A but as B / as A, not as B(Bとしてではなく、Aとして)'], check: ['立場(条件つきでもよい)をはっきり書いた', '理由を2つ書いた', '反対側の心配にもふれた', '指定の語数に入っている', 'feedback に a や s をつけていない'], miss: ['× it can give a quick feedback → ○ give quick feedback(feedback は数えられない)', '× Using AI tools for homework are … → ○ is …'] },

  // --- メール返信 3(40〜60語)---
  { id: 'W2-19', lv: 2, type: 'email', title: 'メール:観光のおすすめ', prompt: '留学生の Alex から次のメールが届きました。2つの質問に答える返信を書きなさい(あいさつと署名もふくめて数えます)。\n\nHi,\nI\'m planning to visit your city next spring. Could you recommend a place to visit and tell me why? Also, what is the best way to get around?\nAlex', words: '40〜60語', model: 'Hi Alex,\nThat\'s great news! I recommend visiting the old castle in the center of the city. In spring, the cherry blossoms around it are really beautiful. The best way to get around is by bus because buses go to most places. I can show you around if you like.\nBest wishes,\nHaruka', alt: [], ja: 'アレックスへ\nすてきな知らせですね!市の中心にある古いお城に行くのがおすすめです。春にはお城のまわりの桜が本当にきれいです。移動するには、ほとんどの場所にバスが行くので、バスがいちばんです。よかったら案内しますよ。\nハルカ', points: ['recommend -ing(〜することをすすめる)', 'get around(あちこち移動する)、by bus(バスで)', 'show 人 around(人を案内する)'], check: ['質問1(おすすめの場所と理由)に答えた', '質問2(移動手段)に答えた', 'あいさつと結びの言葉を書いた', '指定の語数に入っている'], miss: ['× I recommend you to visit the old castle.(recommend -ing か recommend that you visit が自然)', '× by a bus → ○ by bus'] },
  { id: 'W2-20', lv: 2, type: 'email', title: 'メール:先生への提案', prompt: '英語クラブの顧問の Ms. Green から次のメールが届きました。どちらがよいか、理由をそえて返信しなさい(あいさつと署名もふくめて数えます)。\n\nHello everyone,\nFor our next club event, we are thinking of a movie night or a cooking event. Which would you prefer, and why?\nMs. Green', words: '40〜60語', model: 'Dear Ms. Green,\nThank you for planning the event. I would prefer a cooking event. We can learn English words for food while we cook together, and it will be a good chance to talk with each other. Could we make pancakes? They are easy to make.\nBest regards,\nSota', alt: [], ja: 'グリーン先生へ\nイベントを計画してくださってありがとうございます。私は料理のイベントのほうがいいです。いっしょに料理しながら食べ物の英単語を学べますし、おたがいに話すよい機会になります。パンケーキを作るのはどうでしょうか。作るのが簡単です。\nソウタ', points: ['質問が would なので I would prefer 〜. で答える', 'a good chance to 〜(〜するよい機会)', '先生には Could we 〜? のようなていねいな提案を使う'], check: ['どちらがよいかをはっきり書いた', '理由を書いた', 'ていねいな言葉づかいにした', '指定の語数に入っている'], miss: ['× I would prefer cooking event. → ○ a cooking event', '× talk each other → ○ talk with each other'] },
  { id: 'W2-21', lv: 2, type: 'email', title: 'メール:友達へのアドバイス', prompt: '友達の Chris から次のメールが届きました。アドバイスを2つ書いて返信しなさい(あいさつと署名もふくめて数えます)。\n\nHi,\nI\'ve been feeling stressed about my exams. Do you have any advice?\nChris', words: '40〜60語', model: 'Hi Chris,\nI\'m sorry to hear that. I often feel the same way before exams. First, try making a study plan, so you know what to do each day. Second, get enough sleep and take short walks. It really helps me relax. Good luck!\nYour friend,\nNana', alt: [], ja: 'クリスへ\nそれは大変だね。私も試験の前はよく同じ気持ちになるよ。まず、勉強の計画を立ててみて。そうすれば毎日何をすればいいかわかるよ。次に、十分に寝て、少し散歩をしてみて。私はそれで本当にリラックスできるよ。がんばってね!\nナナより', points: ['I\'m sorry to hear that.(それは大変だね)で共感を示す', 'try -ing(試しに〜してみる)', 'help 人 + 原形(人が〜するのに役立つ)'], check: ['相手の気持ちに共感する言葉を書いた', 'アドバイスを2つ書いた', '最後にはげましの言葉を書いた', '指定の語数に入っている'], miss: ['× It really helps me relaxing. → ○ helps me relax', '× get enough sleeps → ○ get enough sleep'] },

  // --- 図表 2(50〜70語)---
  { id: 'W2-22', lv: 2, type: 'graph', title: '図表:図書館と電子書籍', prompt: '次のデータを英語で説明し、考えられる理由を1つ書きなさい。\n\n【A市の利用者数(1年間)】\n・図書館の利用者:2015年 50,000人 → 2018年 42,000人 → 2021年 30,000人\n・電子書籍の利用者:2015年 5,000人 → 2018年 12,000人 → 2021年 25,000人', words: '50〜70語', model: 'The number of people who used the library in City A decreased from 50,000 in 2015 to 30,000 in 2021. On the other hand, the number of e-book users rose sharply from 5,000 to 25,000 during the same period. One possible reason is that more people started reading on their smartphones, so they did not need to visit the library.', alt: [], ja: 'A市で図書館を利用した人の数は、2015年の5万人から2021年の3万人に減少しました。一方、電子書籍の利用者数は同じ期間に5千人から2万5千人へと急増しました。考えられる理由の1つは、スマートフォンで読書を始める人が増え、図書館に行く必要がなくなったことです。', points: ['The number of 〜 decreased / increased from A to B.(数はAからBへ減った/増えた)', 'rise sharply(急に増える)、On the other hand(一方)', 'One possible reason is that 〜.(考えられる理由の1つは〜)'], check: ['2つの数値の変化を両方書いた', '増減を表す動詞と from A to B を正しく使えた', '理由を1つ書いた', '指定の語数に入っている', '過去の変化を過去形で書いた'], miss: ['× The number of people who used the library were decreased. → ○ The number … decreased.(the number は単数、decrease は自動詞)', '× The number of e-book users rose sharp. → ○ rose sharply'] },
  { id: 'W2-23', lv: 2, type: 'graph', title: '図表:家庭学習の時間', prompt: '次のアンケート結果を英語で説明し、あなたの意見を1つ書きなさい。\n\n【高校生が平日に家で勉強する時間】\n・1時間未満:40%\n・1〜2時間:35%\n・2時間以上:25%', words: '50〜70語', model: 'According to the survey, 40 percent of high school students study at home for less than one hour on weekdays. Thirty-five percent study for one to two hours, and only 25 percent study for more than two hours. This shows that most students do not study very long at home. I think they should make a daily plan to study more regularly.', alt: [], ja: 'アンケートによると、高校生の40%は平日に家で1時間未満しか勉強しません。35%は1〜2時間勉強し、2時間以上勉強するのは25%だけです。このことから、ほとんどの生徒は家であまり長く勉強していないことがわかります。私は、もっと規則正しく勉強するために、毎日の計画を立てるべきだと思います。', points: ['According to the survey, 〜.(調査によると)で始める', '〜 percent of …、less than / more than', 'This shows that 〜.(このことから〜がわかる)で読み取りをまとめる'], check: ['3つの数値をすべて説明した', 'less than / more than を正しく使えた', '数値の読み取りと自分の意見を分けて書いた', '指定の語数に入っている', '文頭の数字を英単語で書いた(Thirty-five)'], miss: ['× 35 percent study …(文頭の数字はつづりで書くのが原則 → Thirty-five percent …)', '× 40 percents → ○ 40 percent'] },

  // --- 要約 2(25〜35語)---
  { id: 'W2-24', lv: 2, type: 'summary', title: '要約:ミツバチ', prompt: '次の英文を読んで、内容を英語で要約しなさい。\n\nBees are small, but they play a big role in our lives. When bees fly from flower to flower to collect nectar, they carry pollen. This helps plants produce fruits and seeds. In fact, about one-third of the food we eat depends on bees and other insects. However, the number of bees has been falling in many parts of the world. Scientists say the main causes are the use of chemicals on farms, the loss of wild flowers, and climate change. To protect bees, some cities have started planting more flowers in parks and on rooftops.', words: '25〜35語', model: 'Bees are important because they help plants produce much of our food, but their numbers are falling due to chemicals, habitat loss, and climate change, so people are trying to protect them.', alt: [], ja: 'ミツバチは私たちの食料の多くを植物が生み出すのを助けているため重要ですが、農薬、すみかの減少、気候変動によってその数が減っているので、人々はミツバチを守ろうとしています。', points: ['要約は「重要性 → 問題 → 対策」の流れをおさえる', '具体例(公園や屋上の花)は短くまとめるか省く', 'due to 〜(〜が原因で)で原因をまとめる'], check: ['ミツバチが重要な理由を書いた', '数が減っていることとその原因を書いた', '対策にふれた', '本文をそのまま写さず、自分の言葉でまとめた', '指定の語数に入っている'], miss: ['× 本文の1文目と2文目をそのまま写す(要約は全体の要点を短くまとめる)', '× the number of bees are falling → ○ the number of bees is falling'] },
  { id: 'W2-25', lv: 2, type: 'summary', title: '要約:昼寝の効果', prompt: '次の英文を読んで、内容を英語で要約しなさい。\n\nMany people feel sleepy in the early afternoon. Some companies now allow workers to take a short nap of about 15 to 20 minutes after lunch. Research shows that a short nap can improve concentration and reduce mistakes. However, sleeping for too long can have the opposite effect. If people sleep for more than 30 minutes, they may fall into a deep sleep and feel even more tired when they wake up. Therefore, experts recommend keeping naps short.', words: '25〜35語', model: 'A short nap of 15 to 20 minutes after lunch can improve concentration, but a nap longer than 30 minutes may make people feel more tired, so naps should be short.', alt: [], ja: '昼食後の15〜20分の短い昼寝は集中力を高めますが、30分より長い昼寝はかえって疲れを感じさせることがあるので、昼寝は短くするべきです。', points: ['「よい点 → 注意点 → 結論」を1文にまとめる', 'but や so でつなぐと短くまとまる', 'make 人 feel 〜(人に〜と感じさせる)'], check: ['短い昼寝の効果を書いた', '長すぎる昼寝の問題を書いた', '結論(昼寝は短く)を書いた', '指定の語数に入っている'], miss: ['× a nap longer than 30 minutes may make people to feel more tired → ○ make people feel', '× 会社の例だけを書いて、筆者の結論を書き落とす'] },

  // ===== レベル3(難関大)=====
  // --- 和文英訳 8(日本語らしい表現を組み替える)---
  { id: 'W3-01', lv: 3, type: 'trans', title: '和文英訳:努力が実を結ぶ', prompt: '次の日本語を英語にしなさい。\n「長年の努力がついに実を結んだ。」', words: '', model: 'His years of hard work finally paid off.', alt: ['Her many years of effort were finally rewarded.', 'All the hard work I had done for years finally paid off.'], ja: '長年の努力がついに実を結んだ。', points: ['「実を結ぶ」は pay off / be rewarded が自然(bear fruit も可だが硬い)', '日本語で省かれた主語(だれの努力か)を補う', '「長年の努力」は years of hard work'], check: ['「実を結ぶ」を直訳せず、pay off などで表せた', 'だれの努力かを補った', 'finally を使って「ついに」を表した'], miss: ['× The effort of long years finally made fruits.(直訳で不自然)', '× His years of hard work finally paid. → ○ paid off'] },
  { id: 'W3-02', lv: 3, type: 'trans', title: '和文英訳:様変わり', prompt: '次の日本語を英語にしなさい。\n「この町も、昔とはすっかり様変わりしてしまった。」', words: '', model: 'This town is no longer what it used to be.', alt: ['This town has changed completely over the years.', 'This town has changed beyond recognition.'], ja: 'この町も、昔とはすっかり様変わりしてしまった。', points: ['「昔の〜ではない」は no longer what it used to be', '現在完了 has changed completely でも表せる', '「〜してしまった」は残念な気持ちだが、英語ではふつう表現しなくてよい'], check: ['「様変わりした」を自然な英語で表せた', 'what it used to be(昔の姿)の形を正しく書けた(使った場合)', '時制が正しい(現在完了か現在形)'], miss: ['× This town has changed its appearance completely from the past.(直訳で冗長)', '× This town is no longer what it was used to be. → ○ what it used to be'] },
  { id: 'W3-03', lv: 3, type: 'trans', title: '和文英訳:〜からといって', prompt: '次の日本語を英語にしなさい。\n「忙しいからといって、朝食を抜くのはよくない。」', words: '', model: 'You should not skip breakfast just because you are busy.', alt: ['Being busy is no excuse for skipping breakfast.'], ja: '忙しいからといって、朝食を抜くのはよくない。', points: ['「〜だからといって…ない」は not … just because 〜', '「朝食を抜く」は skip breakfast', '無生物主語で Being busy is no excuse for 〜 とも言える'], check: ['just because を否定と組み合わせて使えた', 'skip breakfast を使えた', '主語(You など一般の人)を補った'], miss: ['× Because you are busy, it is not good to skip breakfast.(「忙しいから抜くのはよくない」と意味がずれる)', '× skip the breakfast → ○ skip breakfast(食事名にはふつう the をつけない)'] },
  { id: 'W3-04', lv: 3, type: 'trans', title: '和文英訳:空気を読む', prompt: '次の日本語を英語にしなさい。\n「日本では、空気を読むことが求められる場面が多い。」', words: '', model: 'In Japan, people are often expected to read the room.', alt: ['In Japan, there are many situations where you are expected to sense what others are thinking without being told.'], ja: '日本では、空気を読むことが求められる場面が多い。', points: ['「空気を読む」は read the room、または内容をかみくだいて sense what others are thinking と説明する', '「求められる」は be expected to 〜', '「場面が多い」は often でまとめると簡潔'], check: ['「空気を読む」を直訳(read the air)しなかった', 'be expected to 〜 を使えた', '「場面が多い」を often や many situations where で表した'], miss: ['× In Japan, there are many scenes that reading the air is required.(直訳で通じない)', '× people are often expected reading the room → ○ expected to read'] },
  { id: 'W3-05', lv: 3, type: 'trans', title: '和文英訳:思い出させる', prompt: '次の日本語を英語にしなさい。\n「彼女に会うたびに、亡くなった祖母のことを思い出す。」', words: '', model: 'She always reminds me of my late grandmother.', alt: ['Whenever I see her, I think of my grandmother, who passed away.'], ja: '彼女に会うたびに、亡くなった祖母のことを思い出す。', points: ['「Aを見るとBを思い出す」は A reminds me of B(無生物・人を主語にする)', '「亡くなった祖母」は my late grandmother / my grandmother, who passed away', '「〜するたびに」は whenever / every time'], check: ['remind A of B の形、または whenever を使えた', '「亡くなった」を late や passed away で表せた', 'my grandmother のあとに関係詞を使う場合、コンマをつけた'], miss: ['× Every time I meet her, I remember my dead grandmother.(dead は直接的すぎる。late / passed away が自然)', '× She reminds me my grandmother. → ○ reminds me of my grandmother'] },
  { id: 'W3-06', lv: 3, type: 'trans', title: '和文英訳:〜すればするほど', prompt: '次の日本語を英語にしなさい。\n「年をとればとるほど、時間がたつのが早く感じられる。」', words: '', model: 'The older we get, the faster time seems to pass.', alt: ['As we grow older, time seems to go by more quickly.'], ja: '年をとればとるほど、時間がたつのが早く感じられる。', points: ['「〜すればするほど…」は The + 比較級 〜, the + 比較級 …', '「感じられる」は seem to 〜', '主語は一般の人を表す we'], check: ['The 比較級, the 比較級 の形を使えた', 'seem to で「感じられる」を表した', 'time に a や the をつけていない'], miss: ['× The more we get old, the more time passes fast. → ○ The older we get, the faster time seems to pass.', '× the faster the time seems to pass(一般的な「時間」に the はつけない)'] },
  { id: 'W3-07', lv: 3, type: 'trans', title: '和文英訳:やってみなければ', prompt: '次の日本語を英語にしなさい。\n「何事も、やってみなければわからない。」', words: '', model: 'You never know until you try.', alt: ['You cannot tell whether something will work unless you try it.'], ja: '何事も、やってみなければわからない。', points: ['「〜してはじめて…」は not … until 〜', '一般の人を主語にするときは you', '「何事も」は訳さなくても意味が伝わる'], check: ['until または unless を使えた', '主語に一般の you を使った', '時を表す節の中を現在形にした'], miss: ['× Anything cannot be known if you don\'t do it.(直訳で不自然)', '× You never know until you will try. → ○ until you try'] },
  { id: 'W3-08', lv: 3, type: 'trans', title: '和文英訳:〜した反面', prompt: '次の日本語を英語にしなさい。\n「この10年で私たちの生活は便利になった反面、人と直接会う機会は減った。」', words: '', model: 'Over the past ten years, our lives have become more convenient, but we have fewer chances to meet people in person.', alt: ['While our lives have become more convenient in the last decade, opportunities to meet people face to face have decreased.'], ja: 'この10年で私たちの生活は便利になった反面、人と直接会う機会は減った。', points: ['「この10年で」は over the past ten years / in the last decade(現在完了と相性がよい)', '「〜した反面」は while 〜 / 〜, but …', '「機会が減った」は we have fewer chances と人を主語にすると英語らしい'], check: ['現在完了で「この10年の変化」を表した', '対比(while / but)を使えた', '「直接」を in person / face to face で表した'], miss: ['× Our life became convenient in these ten years.(「この10年で」には現在完了が自然。lives と複数形に)', '× chances to meet people directly decreased(directly より in person が自然)'] },

  // --- 自由英作文 7(80〜120語)---
  { id: 'W3-09', lv: 3, type: 'free', title: '意見:外国人労働者の受け入れ', prompt: 'Some people say that Japan should accept more foreign workers. Do you agree or disagree? Give reasons to support your opinion.', words: '80〜120語', model: 'I agree that Japan should accept more foreign workers. First, Japan\'s population is aging and shrinking, and many industries, such as nursing care and construction, are already short of workers. Without help from abroad, these important services may not be able to continue. Second, people from different cultures can bring new ideas and skills to Japanese workplaces, which may lead to innovation. Of course, accepting more workers means that Japan must improve language support and protect their rights. However, if the government and companies prepare well, both Japanese society and foreign workers will benefit. For these reasons, I believe Japan should welcome more people from overseas.', alt: [], ja: '私は、日本はもっと外国人労働者を受け入れるべきだという意見に賛成です。第一に、日本の人口は高齢化し減少しており、介護や建設など多くの産業ではすでに人手が足りません。海外からの助けがなければ、こうした大切なサービスが続けられなくなるかもしれません。第二に、異なる文化の人々は日本の職場に新しい考えや技術をもたらし、それが技術革新につながるかもしれません。もちろん、受け入れを増やすには、日本は言語の支援を充実させ、彼らの権利を守らなければなりません。しかし、政府と企業がしっかり準備すれば、日本社会にも外国人労働者にも利益があるでしょう。これらの理由から、私は日本は海外からもっと多くの人を迎えるべきだと考えます。', points: ['be short of 〜(〜が不足している)、lead to 〜(〜につながる)', 'Of course, 〜. However, …. で反論を認めたうえで自分の立場を守る(譲歩→反論)', '社会問題では具体的な業種名(nursing care など)を出すと説得力が出る'], check: ['最初に賛否をはっきり書いた', '理由を2つ書き、それぞれ具体的に説明した', '反対意見や課題にもふれた(譲歩)', '最後に結論をまとめた', '指定の語数に入っている', '関係代名詞・時制・冠詞のミスがない'], miss: ['× Japan\'s population is decreasing and aging, so there are less workers. → ○ fewer workers(数えられる名詞には fewer)', '× which may lead to innovate → ○ lead to innovation(to は前置詞)'] },
  { id: 'W3-10', lv: 3, type: 'free', title: '意見:友達は多いほうがよいか', prompt: 'Is it better to have many friends or a few close friends? Explain your opinion with reasons and examples.', words: '80〜120語', model: 'In my opinion, it is better to have a few close friends than many friends. The main reason is that close friendships require time and trust. If we try to keep in touch with too many people, we cannot spend enough time with each of them, and our relationships may stay shallow. In contrast, a few close friends will understand us deeply and support us when we are in real trouble. For instance, when I was worried about my future, it was my best friend who listened to me for hours and gave me honest advice. Such friends are rare and valuable, so I would rather invest my time in a small number of people.', alt: [], ja: '私の考えでは、多くの友達がいるより、少数の親しい友達がいるほうがよいです。主な理由は、親しい友情には時間と信頼が必要だということです。あまりに多くの人と連絡を取り合おうとすると、一人ひとりと十分な時間を過ごせず、関係が浅いままになるかもしれません。それに対して、少数の親しい友達は私たちを深く理解し、本当に困ったときに支えてくれるでしょう。たとえば、私が将来について悩んでいたとき、何時間も話を聞いて正直なアドバイスをくれたのは親友でした。そのような友達は貴重でかけがえがないので、私はむしろ少数の人に時間を使いたいと思います。', points: ['keep in touch with 〜(〜と連絡を取り合う)、In contrast(それに対して)', '強調構文 it was A who 〜(〜したのはAだった)で印象的な具体例にする', 'would rather 〜(むしろ〜したい)'], check: ['どちらがよいかをはっきり書いた', '理由を論理的に説明した', '自分の経験など具体例を入れた', '最後に結論をまとめた', '指定の語数に入っている'], miss: ['× In my opinion, it is better to have a few close friends than much friends. → ○ many friends(数えられる名詞には many)', '× I would rather to invest → ○ I would rather invest'] },
  { id: 'W3-11', lv: 3, type: 'free', title: '意見:大学の学費無償化', prompt: 'Should university education be free for all students? Write your opinion with reasons.', words: '80〜120語', model: 'I believe university education should be free, or at least much cheaper than it is now. First, free education would give every young person an equal chance. At present, some talented students give up going to university simply because their families cannot afford it. This is a loss not only for them but also for society. Second, a more educated population would help the economy in the long run, since highly skilled workers create new technology and pay more taxes. Some people argue that the cost would be too high for the government. However, I think education should be seen as an investment in the future rather than as an expense.', alt: [], ja: '私は、大学教育は無償にするべきだ、少なくとも今よりずっと安くするべきだと考えます。第一に、無償の教育はすべての若者に平等な機会を与えるでしょう。現在、才能のある学生のなかには、家庭に経済的な余裕がないというだけで大学進学をあきらめる人がいます。これは本人にとってだけでなく、社会にとっても損失です。第二に、教育を受けた人が増えれば、長い目で見て経済を助けるでしょう。高い技能をもつ働き手は新しい技術を生み出し、より多くの税金を納めるからです。費用が政府にとって高すぎると主張する人もいます。しかし私は、教育は支出ではなく未来への投資と見なすべきだと思います。', points: ['afford 〜(〜する経済的余裕がある)、in the long run(長い目で見れば)', 'not only A but also B で影響の広がりを示す', 'Some people argue that 〜. However, …. で反論に答える'], check: ['最初に立場をはっきり書いた', '理由を2つ書いた', '反対意見を取り上げ、それに答えた', '指定の語数に入っている', '仮定の would を一貫して使えた'], miss: ['× their families cannot afford to it → ○ cannot afford it', '× an investment for the future → ○ an investment in the future(invest in 〜)'] },
  { id: 'W3-12', lv: 3, type: 'free', title: '意見:世界が直面する最大の問題', prompt: 'What do you think is the biggest problem the world faces today? Explain why, and suggest how we should deal with it.', words: '80〜120語', model: 'I think the biggest problem facing the world today is climate change. Rising temperatures are causing more frequent heat waves, heavy rain, and droughts, which threaten people\'s lives and food production. Moreover, poorer countries, which have produced the least carbon dioxide, often suffer the most. To deal with this problem, governments should shift from fossil fuels to renewable energy such as solar and wind power. At the same time, each of us can make a difference by saving energy and choosing products that are produced sustainably. Climate change cannot be solved by one country alone, so international cooperation is essential.', alt: [], ja: '私は、今日世界が直面している最大の問題は気候変動だと思います。気温の上昇によって、熱波や豪雨、干ばつがより頻繁に起き、人々の命や食料生産をおびやかしています。さらに、二酸化炭素をもっとも少ししか出していない貧しい国々が、もっとも大きな被害を受けることが多いのです。この問題に対処するために、各国政府は化石燃料から太陽光や風力などの再生可能エネルギーに転換するべきです。同時に、私たち一人ひとりも、省エネをしたり持続可能な方法で作られた製品を選んだりすることで変化をもたらせます。気候変動は1つの国だけでは解決できないので、国際協力が欠かせません。', points: ['the biggest problem facing the world(世界が直面する最大の問題)', 'shift from A to B(AからBへ転換する)、make a difference(変化をもたらす)', '「問題 → 影響 → 対策(国・個人)→ まとめ」の順に書く'], check: ['問題を1つにしぼってはっきり書いた', 'なぜ深刻なのかを具体的に説明した', '対策を提案した', '指定の語数に入っている', '非制限用法の関係代名詞にコンマをつけた'], miss: ['× The biggest problem is a climate change. → ○ climate change(冠詞なし)', '× each of us can make difference → ○ make a difference'] },
  { id: 'W3-13', lv: 3, type: 'free', title: '意見:失敗は成功に必要か', prompt: 'Some people think that failure is necessary for success. Do you agree? Support your opinion with an example.', words: '80〜120語', model: 'I agree that failure is necessary for success. When we fail, we are forced to think about what went wrong and how to improve. This process teaches us lessons that we could never learn from easy success. For example, when I lost in the first round of a speech contest, I watched a recording of my speech and noticed that I spoke too fast. I practiced speaking slowly and clearly, and the next year I won second prize. Without that failure, I would not have grown so much. Therefore, I believe we should not be afraid of failing, but should treat it as a chance to learn.', alt: [], ja: '私は、失敗は成功に必要だという意見に賛成です。失敗すると、何がいけなかったのか、どうすれば改善できるのかを考えざるをえなくなります。この過程は、簡単な成功からは決して学べない教訓を教えてくれます。たとえば、私はスピーチコンテストの1回戦で負けたとき、自分のスピーチの録画を見て、話すのが速すぎたことに気づきました。ゆっくりはっきり話す練習をして、翌年は2位になりました。あの失敗がなければ、これほど成長しなかったでしょう。したがって、私たちは失敗を恐れず、学ぶ機会としてとらえるべきだと思います。', points: ['be forced to 〜(〜せざるをえない)、what went wrong(何がいけなかったか)', 'Without 〜, S would not have 過去分詞(〜がなければ…しなかっただろう)', 'treat A as B(AをBとして扱う)'], check: ['賛否をはっきり書いた', '一般論の理由と、具体的な経験の両方を書いた', '仮定法を正しく使えた(使った場合)', '指定の語数に入っている', '最後に結論をまとめた'], miss: ['× Without that failure, I would not grow so much. → ○ would not have grown(過去の仮定)', '× we should not be afraid of fail → ○ afraid of failing'] },
  { id: 'W3-14', lv: 3, type: 'free', title: '意見:子どものスマートフォン', prompt: 'Do you think children under 13 should have their own smartphones? Give reasons for your opinion.', words: '80〜120語', model: 'I do not think children under 13 should have their own smartphones. First, smartphones can easily become addictive. Young children are not yet good at controlling themselves, so they may spend hours on games and videos instead of studying, playing outside, or sleeping. Second, the internet has many dangers, such as harmful websites and strangers who try to contact children through social media. Children at this age may not be able to recognize these risks. If parents want to contact their children, a simple phone without internet access is enough. When children are older and more responsible, they can start using smartphones safely.', alt: [], ja: '私は、13歳未満の子どもが自分のスマートフォンを持つべきだとは思いません。第一に、スマートフォンは簡単に依存を引き起こします。幼い子どもはまだ自分をコントロールするのが得意ではないので、勉強や外遊び、睡眠の代わりに、何時間もゲームや動画に時間を使ってしまうかもしれません。第二に、インターネットには、有害なサイトや、SNSを通じて子どもに接触しようとする見知らぬ人など、多くの危険があります。この年齢の子どもは、こうした危険に気づけないかもしれません。親が子どもと連絡を取りたいなら、インターネットにつながらないシンプルな電話で十分です。子どもがもっと大きくなって責任感をもてば、安全にスマートフォンを使い始められます。', points: ['addictive(依存性のある)、instead of -ing(〜する代わりに)', 'such as 〜 で具体例を並べる', '代わりの案(a simple phone)を出すと反対意見でも建設的になる'], check: ['最初に立場をはっきり書いた', '理由を2つ書き、それぞれ具体的に説明した', '代案や条件を示した', '指定の語数に入っている', '名詞の単数・複数(websites, strangers)のミスがない'], miss: ['× spend hours to play games → ○ spend hours playing games / spend hours on games', '× Children at this age may not recognize these risk. → ○ these risks'] },
  { id: 'W3-15', lv: 3, type: 'free', title: '意見:観光と地域社会', prompt: 'Some people say that tourism does more harm than good to local communities. To what extent do you agree?', words: '80〜120語', model: 'Although tourism can cause problems, I believe it does more good than harm to local communities. It is true that too many tourists can lead to crowded streets, noise, and rising prices, which make life harder for local residents. However, tourism creates jobs in hotels, restaurants, and shops, and this is especially important for rural areas where young people are leaving. In addition, visitors\' interest can encourage local people to take pride in their traditions and preserve them. The key is to manage tourism carefully, for example by limiting the number of visitors to popular sites. With proper rules, communities can enjoy the benefits while reducing the problems.', alt: [], ja: '観光は問題を引き起こすこともありますが、私は観光は地域社会にとって害より益のほうが大きいと考えます。たしかに、観光客が多すぎると、通りの混雑や騒音、物価の上昇につながり、地元の住民の生活を苦しくすることがあります。しかし、観光はホテルやレストラン、お店に仕事を生み出し、これは若者が出て行ってしまう地方にとって特に重要です。さらに、訪れる人の関心が、地元の人々に自分たちの伝統に誇りをもたせ、それを守ろうという気持ちにさせることもあります。大切なのは、たとえば人気の場所への訪問者数を制限するなどして、観光をうまく管理することです。適切なルールがあれば、地域は問題を減らしながら利益を得られます。', points: ['To what extent 型の問いには「部分的に認める+自分の立場」で答えるとよい', 'It is true that 〜. However, ….(たしかに〜。しかし…)', 'do more good than harm(害より益が大きい)、take pride in 〜(〜に誇りをもつ)'], check: ['どの程度賛成・反対かをはっきり書いた', '相手側の主張を認めたうえで反論した', '具体的な解決策を示した', '指定の語数に入っている', 'harm / good を数えられない名詞として使えた'], miss: ['× tourism does more goods than harms → ○ more good than harm', '× encourage local people take pride → ○ encourage local people to take pride'] },

  // --- 図表 2(80〜110語)---
  { id: 'W3-16', lv: 3, type: 'graph', title: '図表:日本の年齢別人口の割合', prompt: '次のデータから読み取れることを英語で説明し、この変化が生む問題を1つ挙げて、その解決策を述べなさい。\n\n【日本の総人口にしめる割合(数値は概数)】\n・65歳以上:1990年 12% → 2005年 20% → 2020年 29%\n・15歳未満:1990年 18% → 2005年 14% → 2020年 12%', words: '80〜110語', model: 'The data shows that the proportion of people aged 65 and over in Japan more than doubled, from 12 percent in 1990 to 29 percent in 2020. Meanwhile, the share of children under 15 fell from 18 percent to 12 percent. In other words, the number of elderly people has grown while the number of children has declined. One serious problem caused by this trend is a shortage of workers, which makes it difficult to support the pension and medical systems. To solve this problem, Japan should make it easier for older people and women to keep working, and use robots and AI to reduce the burden of labor.', alt: [], ja: 'このデータから、日本の65歳以上の人の割合が、1990年の12%から2020年の29%へと2倍以上になったことがわかります。一方、15歳未満の子どもの割合は18%から12%に下がりました。つまり、高齢者の数が増える一方で、子どもの数は減ってきたのです。この傾向が引き起こす深刻な問題の1つは働き手の不足で、それによって年金や医療の制度を支えることが難しくなります。この問題を解決するために、日本は高齢者や女性が働き続けやすくし、ロボットやAIを使って労働の負担を減らすべきです。', points: ['the proportion / share of 〜(〜の割合)、more than double(2倍以上になる)', 'Meanwhile(一方)、In other words(つまり)で読み取りを整理する', '「読み取り → 問題 → 解決策」の3段階で書く'], check: ['2つのデータの変化を数値をつけて説明した', '変化を自分の言葉でまとめた(In other words など)', '問題を1つ挙げ、理由を説明した', '解決策を書いた', '指定の語数に入っている'], miss: ['× The percentage of old people increased to double.(→ more than doubled)', '× the number of children have declined → ○ has declined'] },
  { id: 'W3-17', lv: 3, type: 'graph', title: '図表:発電方法の内訳', prompt: '次のデータを比べて変化を英語で説明し、それについてのあなたの考えを書きなさい。\n\n【X国の発電の内訳(架空のデータ)】\n・2010年:石炭 50% / 天然ガス 30% / 再生可能エネルギー 10% / 原子力 10%\n・2025年:石炭 30% / 天然ガス 30% / 再生可能エネルギー 35% / 原子力 5%', words: '80〜110語', model: 'The data compares how electricity was produced in Country X in 2010 and 2025. The biggest change is that renewable energy rose from 10 percent to 35 percent, while coal dropped from 50 percent to 30 percent. The share of natural gas stayed the same at 30 percent, and nuclear power fell from 10 percent to 5 percent. These changes suggest that the country has been trying to reduce carbon dioxide emissions. I think this is a positive trend, but renewable energy depends on the weather, so the country will also need better ways to store electricity.', alt: [], ja: 'このデータは、X国で2010年と2025年に電気がどのように作られていたかを比べています。もっとも大きな変化は、再生可能エネルギーが10%から35%に増えた一方で、石炭が50%から30%に減ったことです。天然ガスの割合は30%で変わらず、原子力は10%から5%に下がりました。これらの変化から、この国が二酸化炭素の排出を減らそうとしてきたことがうかがえます。私はこれはよい傾向だと思いますが、再生可能エネルギーは天候に左右されるので、この国は電気をためるよりよい方法も必要になるでしょう。', points: ['いちばん大きな変化から書く(The biggest change is that 〜)', 'stay the same(変わらない)、while(一方で)で対比', 'suggest that 〜(〜ということがうかがえる)で推測を述べる'], check: ['もっとも大きな変化を最初に書いた', '変わらなかった項目にもふれた', '変化の理由の推測と自分の考えを書いた', '指定の語数に入っている', '数値の書き方(from A to B)をそろえた'], miss: ['× Renewable energy was risen to 35 percent. → ○ rose to 35 percent(rise は自動詞)', '× The share of natural gas didn\'t change at 30 percent.(stayed the same at 30 percent が自然)'] },

  // --- 要約 3(40〜60語)---
  { id: 'W3-18', lv: 3, type: 'summary', title: '要約:選択肢が多すぎると', prompt: '次の英文を読んで、内容を英語で要約しなさい。\n\nWhen we go shopping, we usually think that having more choices is a good thing. However, some psychologists argue that too many options can actually make us less happy. In one well-known type of experiment, shoppers are shown either a small or a large selection of a product, such as jam. Although the large display tends to attract more attention, people who see fewer options are often more likely to make a purchase. When there are too many choices, people find it difficult to compare them all, so they may put off the decision. Even after they choose, they may keep wondering whether another option would have been better, which reduces their satisfaction. This does not mean that choice is bad. Rather, it suggests that beyond a certain point, adding more options brings more stress than benefit. Stores and websites that offer a carefully selected range of products may help customers feel more confident about their decisions.', words: '40〜60語', model: 'Although people tend to believe that more choices are better, too many options can make decisions harder and lower satisfaction, because people struggle to compare them and later wonder if another choice was better. Therefore, offering a limited, carefully selected range of options may actually help people feel more confident.', alt: [], ja: '人は選択肢が多いほどよいと考えがちですが、選択肢が多すぎると、比べるのに苦労したり、あとで別のほうがよかったのではと考えたりするため、決断が難しくなり満足度も下がります。したがって、限られた、よく選ばれた選択肢を示すほうが、かえって人に自信をもたせるかもしれません。', points: ['「一般の考え → 筆者の主張 → 理由 → 結論」の順にまとめる', '実験の細部(ジャムなど)は要約では省く', 'Although 〜, …. で一般論と主張の対比を1文にまとめる'], check: ['「選択肢が多すぎると満足度が下がる」という主張を書いた', 'その理由(比べにくい・後悔する)を書いた', '結論(選びぬかれた選択肢がよい)を書いた', '実験の具体例を書きすぎていない', '指定の語数に入っている'], miss: ['× 実験の内容だけをくわしく書き、筆者の主張を書き落とす', '× people find difficult to compare them → ○ people find it difficult to compare them(形式目的語 it が必要)'] },
  { id: 'W3-19', lv: 3, type: 'summary', title: '要約:退屈の価値', prompt: '次の英文を読んで、内容を英語で要約しなさい。\n\nIn today\'s world, we rarely have to feel bored. Whenever we have a few spare minutes, we can take out our smartphones and watch videos, read news, or check messages. At first glance, this seems like a good thing. Yet some researchers believe that boredom has an important role to play. When we have nothing to do, our minds begin to wander, and we start to connect ideas that seem unrelated. This kind of free thinking is often the source of creative ideas. In some studies, people who first did a dull task, such as copying numbers, later came up with more original ideas than those who did not. If we fill every empty moment with information, we may be losing the chance to think deeply and creatively. Occasionally putting our phones away and allowing ourselves to be bored may be good for our minds.', words: '40〜60語', model: 'Although smartphones allow us to avoid boredom, boredom can be valuable because it lets our minds wander and connect ideas, which leads to creativity. By constantly filling our free time with information, we may lose chances to think creatively, so it is sometimes good to put our phones away.', alt: [], ja: 'スマートフォンのおかげで私たちは退屈を避けられますが、退屈は心をさまよわせ、考えを結びつけさせるので、創造性につながる価値があります。空き時間をいつも情報で埋めていると、創造的に考える機会を失うかもしれないので、ときにはスマートフォンをしまうのもよいことです。', points: ['「現状 → 筆者の主張(退屈の価値)→ 理由 → 提案」をおさえる', 'Yet(しかし)のあとに筆者の主張がくることが多い', 'let + 目的語 + 原形(〜させる)'], check: ['「退屈には価値がある」という主張を書いた', 'その理由(考えがつながり創造性が生まれる)を書いた', '筆者の提案(スマホをしまう)を書いた', '自分の言葉で言いかえた', '指定の語数に入っている'], miss: ['× boredom lets our minds to wander → ○ lets our minds wander', '× 研究の具体例(数字を写す作業)だけを書いて主張を落とす'] },
  { id: 'W3-20', lv: 3, type: 'summary', title: '要約:食品ロス', prompt: '次の英文を読んで、内容を英語で要約しなさい。\n\nAround the world, a large amount of food is wasted every year. Some of it is lost on farms and during transport, but a great deal is thrown away by stores and households. In wealthy countries, supermarkets often remove food from their shelves simply because it does not look perfect or because its best-before date is near, even though it is still safe to eat. At home, people buy more than they need and forget about food in the back of the refrigerator. This waste is not only an ethical problem at a time when many people are hungry; it is also an environmental one. Producing, transporting, and disposing of food all use energy and release greenhouse gases. Solutions include selling imperfect vegetables at lower prices, donating unsold food to people in need, and planning meals before shopping.', words: '40〜60語', model: 'A large amount of food is wasted, especially by stores and households, for reasons such as appearance, dates, and buying too much. This waste is both an ethical and an environmental problem, so we should sell imperfect food cheaply, donate unsold food, and plan meals carefully.', alt: [], ja: '大量の食品が、特に店や家庭で、見た目や期限、買いすぎなどの理由で捨てられています。この無駄は倫理的な問題であり環境問題でもあるので、見た目の悪い食品を安く売ったり、売れ残りを寄付したり、食事を計画的に考えたりするべきです。', points: ['「現状 → 原因 → 問題点 → 解決策」をそれぞれ短く', '具体例をまとめる語(appearance, dates など)を使う', 'both A and B で2つの問題を1文にまとめる'], check: ['食品が大量に捨てられている現状を書いた', '主な原因を書いた', '倫理面と環境面の両方の問題にふれた', '解決策を書いた', '指定の語数に入っている'], miss: ['× A large amount of foods are wasted. → ○ A large amount of food is wasted.', '× 原因の具体例(冷蔵庫の奥など)をすべて書いて語数を超える'] }
];
